19	package org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity.conf;
20	
21	import org.apache.hadoop.thirdparty.com.google.common.annotations.VisibleForTesting;
22	import org.apache.hadoop.thirdparty.com.google.common.base.Joiner;
23	import org.slf4j.Logger;
24	import org.slf4j.LoggerFactory;
25	import org.apache.hadoop.conf.Configuration;
26	import org.apache.hadoop.security.UserGroupInformation;
27	import org.apache.hadoop.yarn.conf.YarnConfiguration;
28	import org.apache.hadoop.yarn.server.resourcemanager.RMContext;
29	import org.apache.hadoop.yarn.server.resourcemanager.scheduler.ConfigurationMutationACLPolicy;
30	import org.apache.hadoop.yarn.server.resourcemanager.scheduler.ConfigurationMutationACLPolicyFactory;
31	import org.apache.hadoop.yarn.server.resourcemanager.scheduler.MutableConfigurationProvider;
32	import org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity.CapacitySchedulerConfiguration;
33	import org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity.conf.YarnConfigurationStore.LogMutation;
34	import org.apache.hadoop.yarn.webapp.dao.QueueConfigInfo;
35	import org.apache.hadoop.yarn.webapp.dao.SchedConfUpdateInfo;
36	
37	import java.io.IOException;
38	import java.util.ArrayList;
39	import java.util.Arrays;
40	import java.util.HashMap;
41	import java.util.List;
42	import java.util.Map;
43	import java.util.concurrent.locks.ReentrantReadWriteLock;
44	
45	import static org.apache.hadoop.yarn.server.resourcemanager.scheduler.capacity.CapacitySchedulerConfiguration.ORDERING_POLICY;
46	
47	/**
48	 * CS configuration provider which implements
49	 * {@link MutableConfigurationProvider} for modifying capacity scheduler
50	 * configuration.
51	 */
52	public class MutableCSConfigurationProvider implements CSConfigurationProvider,
53	    MutableConfigurationProvider {
54	
55	  public static final Logger LOG =
56	      LoggerFactory.getLogger(MutableCSConfigurationProvider.class);
57	
58	  private Configuration schedConf;
59	  private Configuration oldConf;
60	  private YarnConfigurationStore confStore;
61	  private ConfigurationMutationACLPolicy aclMutationPolicy;
62	  private RMContext rmContext;
63	
64	  private final ReentrantReadWriteLock formatLock =
65	      new ReentrantReadWriteLock();
66	
67	  public MutableCSConfigurationProvider(RMContext rmContext) {
68	    this.rmContext = rmContext;
69	  }
70	
71	  // Unit test can overwrite this method
72	  protected Configuration getInitSchedulerConfig() {
73	    Configuration initialSchedConf = new Configuration(false);
74	    initialSchedConf.
75	        addResource(YarnConfiguration.CS_CONFIGURATION_FILE);
76	    return initialSchedConf;
77	  }
78	
79	  @Override
80	  public void init(Configuration config) throws IOException {
81	    this.confStore = YarnConfigurationStoreFactory.getStore(config);
82	    Configuration initialSchedConf = getInitSchedulerConfig();
83	    initialSchedConf.addResource(YarnConfiguration.CS_CONFIGURATION_FILE);
84	    this.schedConf = new Configuration(false);
85	    // We need to explicitly set the key-values in schedConf, otherwise
86	    // these configuration keys cannot be deleted when
87	    // configuration is reloaded.
88	    for (Map.Entry<String, String> kv : initialSchedConf) {
89	      schedConf.set(kv.getKey(), kv.getValue());
90	    }
91	    try {
92	      confStore.initialize(config, schedConf, rmContext);
93	      confStore.checkVersion();
94	    } catch (Exception e) {
95	      throw new IOException(e);
96	    }
97	    // After initializing confStore, the store may already have an existing
98	    // configuration. Use this one.
99	    schedConf = confStore.retrieve();
100	    this.aclMutationPolicy = ConfigurationMutationACLPolicyFactory
101	        .getPolicy(config);
102	    aclMutationPolicy.init(config, rmContext);
103	  }
104	
105	  @Override
106	  public void close() throws IOException {
107	    confStore.close();
108	  }
109	
110	  @VisibleForTesting
111	  public YarnConfigurationStore getConfStore() {
112	    return confStore;
113	  }
114	
115	  @Override
116	  public CapacitySchedulerConfiguration loadConfiguration(Configuration
117	      configuration) throws IOException {
118	    Configuration loadedConf = new Configuration(schedConf);
119	    loadedConf.addResource(configuration);
120	    return new CapacitySchedulerConfiguration(loadedConf, false);
121	  }
122	
123	  @Override
124	  public Configuration getConfiguration() {
125	    return new Configuration(schedConf);
126	  }
127	
128	  @Override
129	  public long getConfigVersion() throws Exception {
130	    return confStore.getConfigVersion();
131	  }
132	
133	  @Override
134	  public ConfigurationMutationACLPolicy getAclMutationPolicy() {
135	    return aclMutationPolicy;
136	  }
137	
138	  @Override
139	  public LogMutation logAndApplyMutation(UserGroupInformation user,
140	      SchedConfUpdateInfo confUpdate) throws Exception {
141	    oldConf = new Configuration(schedConf);
142	    CapacitySchedulerConfiguration proposedConf =
143	            new CapacitySchedulerConfiguration(schedConf, false);
144	    Map<String, String> kvUpdate
145	            = constructKeyValueConfUpdate(proposedConf, confUpdate);
146	    LogMutation log = new LogMutation(kvUpdate, user.getShortUserName());
147	    confStore.logMutation(log);
148	    applyMutation(proposedConf, kvUpdate);
149	    schedConf = proposedConf;
150	    return log;
151	  }
152	
153	  public Configuration applyChanges(Configuration oldConfiguration,
154	                           SchedConfUpdateInfo confUpdate) throws IOException {
155	    CapacitySchedulerConfiguration proposedConf =
156	            new CapacitySchedulerConfiguration(oldConfiguration, false);
157	    Map<String, String> kvUpdate
158	            = constructKeyValueConfUpdate(proposedConf, confUpdate);
159	    applyMutation(proposedConf, kvUpdate);
160	    return proposedConf;
161	  }
162	
163	  private void applyMutation(Configuration conf, Map<String, String> kvUpdate) {
164	    for (Map.Entry<String, String> kv : kvUpdate.entrySet()) {
165	      if (kv.getValue() == null) {
166	        conf.unset(kv.getKey());
167	      } else {
168	        conf.set(kv.getKey(), kv.getValue());
169	      }
170	    }
171	  }
172	
173	  @Override
174	  public void formatConfigurationInStore(Configuration config)
175	      throws Exception {
176	    formatLock.writeLock().lock();
177	    try {
178	      confStore.format();
179	      oldConf = new Configuration(schedConf);
180	      Configuration initialSchedConf = new Configuration(false);
181	      initialSchedConf.addResource(YarnConfiguration.CS_CONFIGURATION_FILE);
182	      this.schedConf = new Configuration(false);
183	      // We need to explicitly set the key-values in schedConf, otherwise
184	      // these configuration keys cannot be deleted when
185	      // configuration is reloaded.
186	      for (Map.Entry<String, String> kv : initialSchedConf) {
187	        schedConf.set(kv.getKey(), kv.getValue());
188	      }
189	      confStore.initialize(config, schedConf, rmContext);
190	      confStore.checkVersion();
191	    } catch (Exception e) {
192	      throw new IOException(e);
193	    } finally {
194	      formatLock.writeLock().unlock();
195	    }
196	  }
197	
198	  @Override
199	  public void revertToOldConfig(Configuration config) throws Exception {
200	    formatLock.writeLock().lock();
201	    try {
202	      schedConf = oldConf;
203	      confStore.format();
204	      confStore.initialize(config, oldConf, rmContext);
205	      confStore.checkVersion();
206	    } catch (Exception e) {
207	      throw new IOException(e);
208	    } finally {
209	      formatLock.writeLock().unlock();
210	    }
211	  }
212	
213	  @Override
214	  public void confirmPendingMutation(LogMutation pendingMutation,
215	      boolean isValid) throws Exception {
216	    formatLock.readLock().lock();
217	    try {
218	      confStore.confirmMutation(pendingMutation, isValid);
219	      if (!isValid) {
220	        schedConf = oldConf;
221	      }
222	    } finally {
223	      formatLock.readLock().unlock();
224	    }
225	  }
226	
227	  @Override
228	  public void reloadConfigurationFromStore() throws Exception {
229	    formatLock.readLock().lock();
230	    try {
231	      schedConf = confStore.retrieve();
232	    } finally {
233	      formatLock.readLock().unlock();
234	    }
235	  }
236	
237	  private List<String> getSiblingQueues(String queuePath, Configuration conf) {
238	    String parentQueue = queuePath.substring(0, queuePath.lastIndexOf('.'));
239	    String childQueuesKey = CapacitySchedulerConfiguration.PREFIX +
240	        parentQueue + CapacitySchedulerConfiguration.DOT +
241	        CapacitySchedulerConfiguration.QUEUES;
242	    return new ArrayList<>(conf.getTrimmedStringCollection(childQueuesKey));
243	  }
244	
245	  private Map<String, String> constructKeyValueConfUpdate(
246	      CapacitySchedulerConfiguration proposedConf,
247	      SchedConfUpdateInfo mutationInfo) throws IOException {
248	
249	    Map<String, String> confUpdate = new HashMap<>();
250	    for (String queueToRemove : mutationInfo.getRemoveQueueInfo()) {
251	      removeQueue(queueToRemove, proposedConf, confUpdate);
252	    }
253	    for (QueueConfigInfo addQueueInfo : mutationInfo.getAddQueueInfo()) {
254	      addQueue(addQueueInfo, proposedConf, confUpdate);
255	    }
256	    for (QueueConfigInfo updateQueueInfo : mutationInfo.getUpdateQueueInfo()) {
257	      updateQueue(updateQueueInfo, proposedConf, confUpdate);
258	    }
259	    for (Map.Entry<String, String> global : mutationInfo.getGlobalParams()
260	        .entrySet()) {
261	      confUpdate.put(global.getKey(), global.getValue());
262	    }
263	    return confUpdate;
264	  }
265	
266	  private void removeQueue(
267	      String queueToRemove, CapacitySchedulerConfiguration proposedConf,
268	      Map<String, String> confUpdate) throws IOException {
269	    if (queueToRemove == null) {
270	      return;
271	    } else {
272	      String queueName = queueToRemove.substring(
273	          queueToRemove.lastIndexOf('.') + 1);
274	      if (queueToRemove.lastIndexOf('.') == -1) {
275	        throw new IOException("Can't remove queue " + queueToRemove);
276	      } else {
277	        List<String> siblingQueues = getSiblingQueues(queueToRemove,
278	            proposedConf);
279	        if (!siblingQueues.contains(queueName)) {
280	          throw new IOException("Queue " + queueToRemove + " not found");
281	        }
282	        siblingQueues.remove(queueName);
283	        String parentQueuePath = queueToRemove.substring(0, queueToRemove
284	            .lastIndexOf('.'));
285	        proposedConf.setQueues(parentQueuePath, siblingQueues.toArray(
286	            new String[0]));
287	        String queuesConfig = CapacitySchedulerConfiguration.PREFIX
288	            + parentQueuePath + CapacitySchedulerConfiguration.DOT
289	            + CapacitySchedulerConfiguration.QUEUES;
290	        if (siblingQueues.size() == 0) {
291	          confUpdate.put(queuesConfig, null);
292	          // Unset Ordering Policy of Leaf Queue converted from
293	          // Parent Queue after removeQueue
294	          String queueOrderingPolicy = CapacitySchedulerConfiguration.PREFIX
295	              + parentQueuePath + CapacitySchedulerConfiguration.DOT
296	              + ORDERING_POLICY;
297	          proposedConf.unset(queueOrderingPolicy);
298	          confUpdate.put(queueOrderingPolicy, null);
299	        } else {
300	          confUpdate.put(queuesConfig, Joiner.on(',').join(siblingQueues));
301	        }
302	        for (Map.Entry<String, String> confRemove : proposedConf.getValByRegex(
303	            ".*" + queueToRemove.replaceAll("\\.", "\\.") + "\\..*")
304	            .entrySet()) {
305	          proposedConf.unset(confRemove.getKey());
306	          confUpdate.put(confRemove.getKey(), null);
307	        }
308	      }
309	    }
310	  }
311	
312	  private void addQueue(
313	      QueueConfigInfo addInfo, CapacitySchedulerConfiguration proposedConf,
314	      Map<String, String> confUpdate) throws IOException {
315	    if (addInfo == null) {
316	      return;
317	    } else {
318	      String queuePath = addInfo.getQueue();
319	      String queueName = queuePath.substring(queuePath.lastIndexOf('.') + 1);
320	      if (queuePath.lastIndexOf('.') == -1) {
321	        throw new IOException("Can't add invalid queue " + queuePath);
322	      } else if (getSiblingQueues(queuePath, proposedConf).contains(
323	          queueName)) {
324	        throw new IOException("Can't add existing queue " + queuePath);
325	      }
326	      String parentQueue = queuePath.substring(0, queuePath.lastIndexOf('.'));
327	      String[] siblings = proposedConf.getQueues(parentQueue);
328	      List<String> siblingQueues = siblings == null ? new ArrayList<>() :
329	          new ArrayList<>(Arrays.<String>asList(siblings));
330	      siblingQueues.add(queuePath.substring(queuePath.lastIndexOf('.') + 1));
331	      proposedConf.setQueues(parentQueue,
332	          siblingQueues.toArray(new String[0]));
333	      confUpdate.put(CapacitySchedulerConfiguration.PREFIX
334	              + parentQueue + CapacitySchedulerConfiguration.DOT
335	              + CapacitySchedulerConfiguration.QUEUES,
336	          Joiner.on(',').join(siblingQueues));
337	      String keyPrefix = CapacitySchedulerConfiguration.PREFIX
338	          + queuePath + CapacitySchedulerConfiguration.DOT;
339	      for (Map.Entry<String, String> kv : addInfo.getParams().entrySet()) {
340	        if (kv.getValue() == null) {
341	          proposedConf.unset(keyPrefix + kv.getKey());
342	        } else {
343	          proposedConf.set(keyPrefix + kv.getKey(), kv.getValue());
344	        }
345	        confUpdate.put(keyPrefix + kv.getKey(), kv.getValue());
346	      }
347	      // Unset Ordering Policy of Parent Queue converted from
348	      // Leaf Queue after addQueue
349	      String queueOrderingPolicy = CapacitySchedulerConfiguration.PREFIX
350	          + parentQueue + CapacitySchedulerConfiguration.DOT + ORDERING_POLICY;
351	      if (siblingQueues.size() == 1) {
352	        proposedConf.unset(queueOrderingPolicy);
353	        confUpdate.put(queueOrderingPolicy, null);
354	      }
355	    }
356	  }
357	
358	  private void updateQueue(QueueConfigInfo updateInfo,
359	      CapacitySchedulerConfiguration proposedConf,
360	      Map<String, String> confUpdate) {
361	    if (updateInfo == null) {
362	      return;
363	    } else {
364	      String queuePath = updateInfo.getQueue();
365	      String keyPrefix = CapacitySchedulerConfiguration.PREFIX
366	          + queuePath + CapacitySchedulerConfiguration.DOT;
367	      for (Map.Entry<String, String> kv : updateInfo.getParams().entrySet()) {
368	        String keyValue = kv.getValue();
369	        if (keyValue == null || keyValue.isEmpty()) {
370	          keyValue = null;
371	          proposedConf.unset(keyPrefix + kv.getKey());
372	        } else {
373	          proposedConf.set(keyPrefix + kv.getKey(), keyValue);
374	        }
375	        confUpdate.put(keyPrefix + kv.getKey(), keyValue);
376	      }
377	    }
378	  }
379	}
