      updateForRoot);

  Map<String, String> updateForRootA = new HashMap<>();
  updateForRootA.put(ACCESSIBLE_NODE_LABELS, LABEL_1);
  QueueConfigInfo rootAUpdateInfo = new QueueConfigInfo(
      ROOT_A.getFullPath(), updateForRootA);

  // 7. Check residual configs
  assertNull(getConfValueForQueueAndLabelAndType(cs, ROOT, LABEL_1,
